def test_{target}_source_shape():
    seg = _{func}_seg()
    assert "{must_have}" in seg
    assert "{must_absent}" not in seg
    # 红先对照：{head_count_cmd}

def test_{symbol}_exists():
    out = {module}.{symbol}({call_args})
    assert out["ok"] is True

def test_{write_fn}_rejects_forbidden_key():
    out = {write_fn}(state, "{forbidden_key}", val)
    assert out["ok"] is False and "{kw}" in out["error"]


def test_{write_fn}_allows_allowed_key():
    # 负臂：合规键须仍可写（防过度收紧成「全禁」）
    assert {write_fn}(state, "{allowed_key}", val)["ok"] is True

def test_{audit_fn}_flags_bad_combination():
    out = {audit_fn}(state_with({bad_entry}))
    assert out["status"] == "FAIL" and "{flag}" in out["detail"]


def test_{audit_fn}_honors_escape_and_regression():
    assert {audit_fn}(state_with({escape_entry}))["status"] == "PASS"

def test_{target}_fixture_truth(tmp_path):
    fx = {env_fn}(tmp_path)              # 真 git 夹具
    assert {run_fn}(fx) == {prior}        # 构造先验（禁回读）


def test_{target}_negative_missing(tmp_path):
    assert {run_fn}({negative1}) == "fail-loud"


def test_{target}_meta_tamper_must_deviate(tmp_path):
    fx = {env_fn}(tmp_path)
    {tamper}(fx)                          # 已知篡改
    assert {run_fn}(fx) != {prior}         # 元判据：篡改后必偏离

def test_{gate_fn}_fires_on_known_violation():
    bad = {gate_fn}({bad_input})
    assert bad["status"] == "FAIL" and "{flag}" in bad["detail"]


def test_{gate_fn}_good_and_bad_differ():
    # 差异臂：好/坏输入判决**必须不同**（治硬编码假证据 / 恒不触发）
    assert {gate_fn}({good_input})["status"] == "PASS"
    assert {gate_fn}({bad_input})["status"] != {gate_fn}({good_input})["status"]


def test_{gate_name}_is_wired_into_{agg_fn}():
    # 接线臂：闸门须被聚合入口真调用（防『部分模组未接线』）
    assert "{gate_fn}" in _{agg_fn}_seg()

def test_{target}_uses_single_source():
    for name in ("{consumer_a}", "{consumer_b}"):
        txt = (SCRIPT_DIR / name).read_text(encoding="utf-8")
        assert "{shared_symbol}" in txt, "%s 未接单一源" % name
        assert "{old_marker}" not in txt, "%s 仍有旧的自算路径" % name
